using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// 2) Non-throwing probe: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about Person, so Widget is unknown.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new LimitedResolver())
};

bool havePerson = limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pInfo);
bool haveWidget = limitedOptions.TryGetTypeInfo(typeof(Widget), out JsonTypeInfo? wInfo);

Console.WriteLine($"\nProbing with limited resolver:");
Console.WriteLine($"  Person available? {havePerson} (info: {pInfo?.Type.Name ?? "null"})");
Console.WriteLine($"  Widget available? {haveWidget} (info: {wInfo?.Type.Name ?? "null"})");

// --- Types ---
record Person(string Name, int Age);
record Widget(string Sku);

// A resolver that only provides metadata for Person
class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // unknown type
    }
}

